// CEKIVA publishing: one POST /v1/posts per platform, each with the copy the AI wrote for THAT platform.
const CONFIG = {
  CLIENT_ID: '',      // optional: id of one of your CEKIVA client workspaces (GET https://cekiva.com/api/v1/clients); empty = your primary workspace
  PUBLISH_NOW: true,  // true = publish right away (what the original did); false = publish at SCHEDULED_AT
  SCHEDULED_AT: '',   // ISO 8601 with a time zone, e.g. 2026-12-01T09:00:00Z (used only when PUBLISH_NOW is false)
};

const posts = ($('Social Media Content Factory').first().json.output || {}).platform_posts || {};
const form = $('Submit Social Post Details').first().json || {};
const upload = $input.first().json; // the answer of the ImgBB upload
const imageUrl = (upload.data && ((upload.data.medium && upload.data.medium.url) || upload.data.url)) || null;
const clientId = String(form.client_id || CONFIG.CLIENT_ID || '').trim();

const join = (...parts) => parts.filter((x) => typeof x === 'string' && x.trim()).map((x) => x.trim()).join('\n\n');
const tags = (list) => (Array.isArray(list) ? list.join(' ') : '');
const ig = posts.Instagram || {}; const fb = posts.Facebook || {}; const li = posts.LinkedIn || {};
// keys = CEKIVA platform ids. X/Twitter is not here: CEKIVA retired that channel.
const copy = {
  instagram: join(ig.caption),
  facebook_page: join(fb.post, fb.call_to_action),
  linkedin: join(li.post, li.call_to_action, tags(li.hashtags)),
};

const scheduleAt = !CONFIG.PUBLISH_NOW && CONFIG.SCHEDULED_AT ? CONFIG.SCHEDULED_AT : null;
return Object.entries(copy)
  .filter(([, text]) => text)
  .map(([platform, content]) => {
    // The body of POST /v1/posts exactly as the CEKIVA API expects it.
    const request = { platforms: [platform], content, scheduled_for: scheduleAt || new Date().toISOString(), publish_now: !scheduleAt };
    if (imageUrl) { request.image_url = imageUrl; request.media_urls = [imageUrl]; } // Instagram needs an image: without one CEKIVA answers IMAGE_REQUIRED for that row
    if (clientId) request.client_id = clientId;
    return { json: { platform, request } };
  });

// One uniform row per platform for the results summary (Aggregate → Prepare Results ...).
const sent = $('Build CEKIVA posts').all();
return $input.all().map((item, i) => {
  const r = item.json;
  const platform = sent[i] ? sent[i].json.platform : 'unknown';
  const body = r.body;
  const post = Array.isArray(body) ? body[0] : null;
  const err = body && !Array.isArray(body) && body.error && typeof body.error === 'object' ? body.error : null;
  const status = Number(r.statusCode) || null;
  const ok = status !== null && status >= 200 && status < 300 && !!post;
  return { json: {
    platform,
    result: ok ? 'Success' : 'Error',
    http_status: status,
    post_id: post ? post.id : null,
    post_status: post ? post.status : null,
    credits_charged: post ? post.credits_charged : null,
    error_code: err ? err.code : (r.error ? 'CEKIVA_UNREACHABLE' : null),
    error_message: err ? err.message : (r.error ? String(r.error.message || r.error).slice(0, 200) : (ok ? null : 'Unexpected response')),
    hint: err ? err.hint : null,
  } };
});
